try:
 import vtk; print('vtk', vtk.vtkVersion().GetVTKVersion())
except Exception as e: print(e)
try:
 import paraview; print('paraview')
except Exception as e: print('no paraview', e)
try:
 import topologytoolkit; print('ttk', topologytoolkit)
except Exception as e: print('no ttk',e)
PY
ls -l /opt/conda/bin | rg 'para|pv|ttk' || true
find /opt/conda/lib/python3.13/site-packages/topologytoolkit -maxdepth 1 -type f | head -40"

