import sys
print('\\n'.join(sys.path))
try:
 import topologytoolkit.ttkTopologicalSimplificationByPersistence as m
 print('mod',dir(m))
except Exception as e: print('ERR',repr(e))
try:
 from paraview.simple import *
 print('simple loaded')
 print([x for x in dir() if 'Topological' in x or 'Critical' in x or 'Persistence' in x][:40])
except Exception as e: print('simple err',repr(e))
PY"

